// The onboarding explainer video (SPEC §26.7.4). Scenes follow szoveg/sorok.json; every timing comes from adat.json
// (generated by eszkoz/render.py from hang/idozites.json), so a new voice take or a changed line needs no code change.
import React from 'react';
import { AbsoluteFill, interpolate, Sequence, spring, useCurrentFrame, useVideoConfig } from 'remotion';
import adat from './adat.json';
import {
  Avatar,
  be,
  BETU,
  C,
  Cimke,
  el,
  Fejcim,
  Fulsor,
  Ikon,
  Kapszula,
  Korong,
  Lap,
  M,
  megjelen,
  pattan,
  Rozetta,
  SAV_ALAP,
  Targy,
  useGeist,
  W,
} from './elemek';

type Adat = typeof adat;
type Jel = Adat['jelenetek'][number];

const SOR: Record<string, { tol: number; ig: number }> = Object.fromEntries(adat.sorok.map((s) => [s.id, { tol: s.tol, ig: s.ig }]));
const CUE_SORONKENT: Record<string, { tol: number; ig: number }[]> = {};
for (const s of adat.sorok) {
  CUE_SORONKENT[s.id] = adat.cues.filter((c) => c.tol >= s.tol - 1 && c.ig <= s.ig + 1).map((c) => ({ tol: c.tol, ig: c.ig }));
}
/** Lines whose words are already on screen as big text: no burned-in caption (the VTT still has them). */
const NINCS_FELIRAT = new Set(['L01', 'L02', 'L22']);

/** Band height and rosette per scene. */
const SAV: Record<string, { mag: number; rx: number; ry: number }> = {
  koszonto: { mag: 1180, rx: 540, ry: 640 },
  zaro: { mag: 1920, rx: 540, ry: 760 },
};
const savOf = (id: string) => SAV[id] ?? { mag: SAV_ALAP, rx: 900, ry: 170 };

type JP = { f: number; L: (id: string) => number; cue: (id: string, i: number) => number; dur: number };

// ------------------------------------------------------------------------------------------------ shared scene parts
const SavCim: React.FC<{ f: number; felso?: React.ReactNode; cim: string; kesleltet?: number }> = ({ f, felso, cim, kesleltet = 0 }) => {
  const p = be(f, 7 + kesleltet, 14);
  return (
    <div style={{ position: 'absolute', left: M + 12, right: M + 12, top: 92, color: '#FFFFFF', ...megjelen(p, 24) }}>
      {felso ? <div style={{ fontSize: 38, fontWeight: 600, color: C.fejlecHalvany, marginBottom: 14, letterSpacing: '-0.005em' }}>{felso}</div> : null}
      <div style={{ fontSize: 86, fontWeight: 700, lineHeight: 1.08, letterSpacing: '-0.026em' }}>{cim}</div>
    </div>
  );
};

const SavAlcim: React.FC<{ f: number; szoveg: string }> = ({ f, szoveg }) => (
  <div style={{ position: 'absolute', left: M + 12, top: 316, fontSize: 46, fontWeight: 500, color: C.fejlecHalvany, ...megjelen(be(f, 10, 14), 14) }}>
    {szoveg}
  </div>
);

/** Progress rail on the band: done = the violet 3D seal, current = white disc, remaining = faint disc. */
const Sin: React.FC<{ f: number; most: number; kesz: number }> = ({ f, most, kesz }) => (
  <div style={{ position: 'absolute', left: M + 12, top: 342, display: 'flex', gap: 24, alignItems: 'center' }}>
    {[1, 2, 3, 4, 5].map((n, i) => {
      const p = be(f, 9 + i * 3, 12);
      if (n <= kesz) return <Ikon key={n} nev="befizetve" meret={68} style={{ opacity: p }} />;
      return (
        <div key={n} style={{ opacity: p }}>
          <Korong n={n} allapot={n === most ? 'savon_most' : 'savon_hatra'} meret={64} />
        </div>
      );
    })}
  </div>
);

const LapTartalom: React.FC<{ f: number; top?: number; height?: number; children: React.ReactNode; kesleltet?: number }> = ({
  f,
  top = 528,
  height = 900,
  children,
  kesleltet = 4,
}) => {
  const p = be(f, kesleltet, 16);
  return (
    <Lap style={{ top, height, ...megjelen(p, 60) }}>
      <div style={{ position: 'absolute', inset: 0, padding: '56px 60px', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>{children}</div>
    </Lap>
  );
};

const Allitas: React.FC<{ szoveg: React.ReactNode; p: number; meret?: number; style?: React.CSSProperties }> = ({ szoveg, p, meret = 62, style }) => (
  <div style={{ fontSize: meret, fontWeight: 700, lineHeight: 1.12, letterSpacing: '-0.022em', color: C.tinta, textAlign: 'center', textWrap: 'balance', ...megjelen(p, 26), ...style } as React.CSSProperties}>
    {szoveg}
  </div>
);

const Blokk: React.FC<{ cim: string; szoveg: React.ReactNode; p: number; style?: React.CSSProperties }> = ({ cim, szoveg, p, style }) => (
  <div style={{ width: '100%', ...megjelen(p, 22), ...style }}>
    <Fejcim szoveg={cim} />
    <div style={{ fontSize: 48, fontWeight: 550, lineHeight: 1.3, color: C.tinta, marginTop: 10, letterSpacing: '-0.01em', textWrap: 'pretty' } as React.CSSProperties}>{szoveg}</div>
  </div>
);

const Hajszal: React.FC = () => <div style={{ height: 3, background: C.hajszal, width: '100%' }} />;

// ------------------------------------------------------------------------------------------------ scenes
const Koszonto: React.FC<JP> = ({ f, L }) => {
  const { fps } = useVideoConfig();
  const p2 = be(f, Math.max(4, L('L01') - 4), 18);
  const p3 = be(f, L('L02') - 2, 16);
  const p4 = spring({ frame: f - (L('L01') + 36), fps, config: { damping: 16, stiffness: 120 } });
  return (
    <>
      <div
        style={{
          position: 'absolute',
          left: M + 20,
          right: M + 20,
          top: 500,
          textAlign: 'center',
          color: '#FFFFFF',
          fontSize: 100,
          fontWeight: 700,
          lineHeight: 1.08,
          letterSpacing: '-0.03em',
          ...megjelen(p2, 30),
        }}
      >
        Köszönjük, hogy telepítetted az alkalmazásunkat!
      </div>
      <div
        style={{
          position: 'absolute',
          left: M + 20,
          right: M + 20,
          top: 900,
          textAlign: 'center',
          color: C.fejlecHalvany,
          fontSize: 54,
          fontWeight: 500,
          lineHeight: 1.3,
          ...megjelen(p3, 20),
        }}
      >
        Megmutatjuk, mire jó,
        <br />
        és mi kell a kezdéshez.
      </div>
      <div style={{ position: 'absolute', left: M, right: M, top: 1540, opacity: Math.min(1, p4 * 1.5), transform: `translateY(${(1 - p4) * 160}px)` }}>
        <Fulsor />
      </div>
    </>
  );
};

const MireJo: React.FC<JP> = ({ f, L }) => {
  const { fps } = useVideoConfig();
  const kartyak: { id: string; vizual: React.ReactNode; cim: string; al: string }[] = [
    { id: 'L03', vizual: <Avatar meret={148} />, cim: 'Saját könyvelő', al: 'Intézi az adóidat.' },
    // SPEC §27.5 (owner order 5, 11-19): one wording – "Kiállított számlák", they appear by themselves, no upload
    { id: 'L04', vizual: <Ikon nev="szamlak" meret={160} />, cim: 'Kiállított számlák', al: 'Maguktól megjelennek.' },
    { id: 'L05', vizual: <Ikon nev="szamolo" meret={150} />, cim: 'Mennyit, mikorra, hova', al: 'A Főoldalon látod.' },
    { id: 'L06', vizual: <Ikon nev="fotozas" meret={156} />, cim: 'Csak lefotózod', al: 'Nyugták, papírok.' },
  ];
  return (
    <>
      <SavCim f={f} felso="Az alkalmazás" cim="Mire jó?" />
      <SavAlcim f={f} szoveg="Ezt kapod tőlünk" />
      {kartyak.map((k, i) => {
        const t = Math.max(6, L(k.id) - 6);
        const p = be(f, t, 16);
        const v = spring({ frame: f - t - 4, fps, config: { damping: 13, stiffness: 140 } });
        return (
          <Lap key={k.id} style={{ top: 520 + i * 226, height: 204, opacity: p, transform: `translateX(${(1 - p) * 90}px)` }}>
            <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', gap: 40, padding: '0 44px' }}>
              <div style={{ width: 168, height: 168, display: 'flex', alignItems: 'center', justifyContent: 'center', ...pattan(v) }}>{k.vizual}</div>
              <div>
                <div style={{ fontSize: 56, fontWeight: 700, letterSpacing: '-0.02em', color: C.tinta, lineHeight: 1.1 }}>{k.cim}</div>
                <div style={{ fontSize: 42, fontWeight: 500, color: C.halvany, marginTop: 8 }}>{k.al}</div>
              </div>
            </div>
          </Lap>
        );
      })}
    </>
  );
};

const Bekotes: React.FC<JP> = ({ f, cue }) => {
  const sorok: { n: number | null; ikon: string; cim: string; al?: string; cimke?: string }[] = [
    { n: 1, ikon: 'fiok', cim: 'Adataid' },
    { n: null, ikon: 'bevallas', cim: 'Vállalkozás bejelentése', cimke: 'Ha még nincs vállalkozásod' },
    { n: 2, ikon: 'irat', cim: 'Szerződés és havidíj' },
    { n: 3, ikon: 'igazolas', cim: 'NAV-meghatalmazás' },
    { n: 4, ikon: 'fotozas', cim: 'Igazolványok' },
    { n: 5, ikon: 'szamlak', cim: 'Összekötés a NAV-val', al: 'A könyvelőd intézi' },
  ];
  const chipStart = cue('L07', 1);
  return (
    <>
      <SavCim f={f} felso="Néhány lépés" cim="A bekötés" />
      <div style={{ position: 'absolute', left: M + 12, top: 316, display: 'flex', gap: 18 }}>
        {['Mi ez?', 'Miért kell?', 'Hol találod?'].map((t, i) => {
          const p = be(f, chipStart + i * 9, 12);
          return <Kapszula key={t} szoveg={t} tipus="savon" style={{ ...megjelen(p, 18) }} />;
        })}
      </div>
      <Lap style={{ top: 520, height: 900, ...megjelen(be(f, 2, 16), 50) }}>
        <div style={{ position: 'absolute', inset: 0, padding: '30px 44px', display: 'flex', flexDirection: 'column' }}>
          {sorok.map((s, i) => {
            const p = be(f, 8 + i * 6, 14);
            return (
              <React.Fragment key={s.cim}>
                {i > 0 ? <Hajszal /> : null}
                <div style={{ height: 136, display: 'flex', alignItems: 'center', gap: 30, paddingLeft: s.n === null ? 94 : 0, ...megjelen(p, 20) }}>
                  {s.n !== null ? <Korong n={s.n} allapot="hatra" meret={64} /> : null}
                  <Ikon nev={s.ikon} meret={96} />
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: 48, fontWeight: 650, color: C.tinta, letterSpacing: '-0.015em', lineHeight: 1.1 }}>{s.cim}</div>
                    {s.al ? <div style={{ fontSize: 36, color: C.halvany, marginTop: 6 }}>{s.al}</div> : null}
                    {s.cimke ? <Cimke szoveg={s.cimke} meret={32} style={{ marginTop: 10 }} /> : null}
                  </div>
                </div>
              </React.Fragment>
            );
          })}
        </div>
      </Lap>
    </>
  );
};

const LepesAdatok: React.FC<JP> = ({ f, L, cue }) => {
  const { fps } = useVideoConfig();
  const v = spring({ frame: f - 10, fps, config: { damping: 13, stiffness: 140 } });
  return (
    <>
      <SavCim f={f} felso="1. lépés" cim="Adataid" />
      <Sin f={f} most={1} kesz={0} />
      <LapTartalom f={f}>
        <div style={pattan(v)}>
          <Ikon nev="fiok" meret={230} />
        </div>
        <Allitas szoveg="Néhány adat rólad" p={be(f, 16, 16)} style={{ marginTop: 34 }} />
        <div style={{ height: 50 }} />
        <Blokk cim="Miért kell?" szoveg="Ezekből számol a könyvelőd." p={be(f, cue('L08', 1) - 4, 14)} />
        <div style={{ height: 40 }} />
        <Blokk cim="Hol találod?" szoveg="Az adóazonosító jeled az adóigazolványodon van." p={be(f, cue('L08', 1) + 26, 14)} />
      </LapTartalom>
    </>
  );
};

const LepesInditas: React.FC<JP> = ({ f, L, dur }) => {
  const { fps } = useVideoConfig();
  const tA = 0;
  const tB = L('L10') - 6;
  const tC = L('L10b') - 6;
  const opA = be(f, tA + 4, 14) * el(f, tB + 8, 10);
  const opB = be(f, tB + 6, 14) * el(f, tC + 8, 10);
  const opC = be(f, tC + 6, 14);
  const vA = spring({ frame: f - 10, fps, config: { damping: 13, stiffness: 140 } });
  const vC = spring({ frame: f - tC - 12, fps, config: { damping: 13, stiffness: 140 } });
  const pecset = spring({ frame: f - (tC + Math.round((L('L10b') - tC) + 48)), fps, config: { damping: 11, stiffness: 170 } });
  const jelolesek: [string, string, 'tinta' | 'semleges'][] = [
    ['Alanyi áfamentesség', 'IGEN', 'tinta'],
    ['Átalányadózás', 'IGEN', 'tinta'],
    ['Kata', 'NEM', 'semleges'],
    ['Pénzforgalmi elszámolás', 'NEM', 'semleges'],
  ];
  return (
    <>
      <div style={{ position: 'absolute', left: M + 12, top: 92, ...megjelen(be(f, 7, 14), 20) }}>
        <Cimke szoveg="Ha még nincs vállalkozásod" meret={38} />
      </div>
      <div style={{ position: 'absolute', left: M + 12, right: M + 12, top: 176, color: '#FFFFFF', ...megjelen(be(f, 8, 14), 24) }}>
        <div style={{ fontSize: 86, fontWeight: 700, lineHeight: 1.08, letterSpacing: '-0.026em' }}>Vállalkozás indítása</div>
        <div style={{ fontSize: 42, fontWeight: 500, color: C.fejlecHalvany, marginTop: 18 }}>Saját útmutatóval, lépésről lépésre</div>
      </div>
      <Lap style={{ top: 528, height: 900, ...megjelen(be(f, 2, 16), 60) }}>
        {/* A: you file it yourself */}
        <div style={{ position: 'absolute', inset: 0, padding: '56px 60px', display: 'flex', flexDirection: 'column', alignItems: 'center', opacity: opA }}>
          <div style={pattan(vA)}>
            <Targy nev="tepnaptar_3d" szel={210} mag={256} arnyek={170} />
          </div>
          <Allitas szoveg={<>Te jelented be,<br />a NAV oldalán</>} p={be(f, 16, 16)} style={{ marginTop: 40 }} />
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 18, justifyContent: 'center', marginTop: 44 }}>
            {['Ügyfélkapu+ vagy DÁP', 'Kb. 10–15 perc', 'Ingyenes'].map((t, i) => (
              <Cimke key={t} szoveg={t} tipus="semleges" meret={38} style={{ ...megjelen(be(f, 30 + i * 8, 12), 14) }} />
            ))}
          </div>
        </div>
        {/* B: what to tick */}
        <div style={{ position: 'absolute', inset: 0, padding: '60px 64px', display: 'flex', flexDirection: 'column', opacity: opB }}>
          <Fejcim szoveg="Mit hova jelölj" />
          <div style={{ fontSize: 58, fontWeight: 700, color: C.tinta, letterSpacing: '-0.02em', marginTop: 12, marginBottom: 26 }}>A NAV űrlapján</div>
          {jelolesek.map(([cim, ertek, tipus], i) => (
            <React.Fragment key={cim}>
              <Hajszal />
              <div style={{ height: 150, display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 20, ...megjelen(be(f, tB + 14 + i * 10, 12), 16) }}>
                <div style={{ fontSize: 48, fontWeight: 600, color: C.tinta, letterSpacing: '-0.012em' }}>{cim}</div>
                <Cimke szoveg={ertek} tipus={tipus} meret={40} />
              </div>
            </React.Fragment>
          ))}
          <Hajszal />
          <div style={{ fontSize: 36, color: C.halvany, marginTop: 26, ...megjelen(be(f, tB + 60, 12), 10) }}>
            Minden mezőt megmutatunk, képpel.
          </div>
        </div>
        {/* C: upload the confirmation, we check it; then the chamber */}
        <div style={{ position: 'absolute', inset: 0, padding: '56px 60px', display: 'flex', flexDirection: 'column', alignItems: 'center', opacity: opC }}>
          <div style={{ position: 'relative', ...pattan(vC) }}>
            <Ikon nev="feltoltes" meret={220} />
            <div style={{ position: 'absolute', right: -40, top: -18, ...pattan(pecset) }}>
              <Ikon nev="befizetve" meret={110} />
            </div>
          </div>
          <Allitas szoveg={<>Feltöltöd a NAV-os<br />igazolást</>} p={be(f, tC + 16, 16)} style={{ marginTop: 36 }} />
          <div style={{ fontSize: 48, fontWeight: 550, color: C.halvany, marginTop: 18, textAlign: 'center', ...megjelen(be(f, tC + 40, 14), 14) }}>
            Átnézzük, és szólunk.
          </div>
          <div style={{ marginTop: 46, ...megjelen(be(f, tC + 70, 14), 14) }}>
            <div
              style={{
                background: C.borostyanAlap,
                color: C.borostyan,
                borderRadius: 16,
                padding: '18px 26px',
                fontSize: 38,
                fontWeight: 650,
                lineHeight: 1.3,
                textAlign: 'center',
              }}
            >
              Utána: kamarai regisztráció,
              <br />5 munkanapon belül
            </div>
          </div>
        </div>
      </Lap>
    </>
  );
};

