const JELENETEK: Record<string, React.FC<JP>> = {
  koszonto: Koszonto,
  mire_jo: MireJo,
  bekotes: Bekotes,
  lepes_adatok: LepesAdatok,
  lepes_inditas: LepesInditas,
  lepes_szerzodes: LepesSzerzodes,
  lepes_meghatalmazas: LepesMeghatalmazas,
  lepes_azonositas: LepesAzonositas,
  lepes_szamlak: LepesSzamlak,
  korlatozott: Korlatozott,
  segitseg: Segitseg,
  zaro: Zaro,
};

// ------------------------------------------------------------------------------------------------ global layers
const ATMENET = 14; // band transition
const KI_ATMENET = 8; // the outgoing scene fades out during the first frames of the next one

const Sav: React.FC = () => {
  const f = useCurrentFrame();
  const js = adat.jelenetek;
  let i = js.findIndex((j) => f >= j.tol && f < j.ig);
  if (i < 0) i = js.length - 1;
  const most = savOf(js[i].id);
  const elozo = i > 0 ? savOf(js[i - 1].id) : most;
  const t = interpolate(f, [js[i].tol, js[i].tol + ATMENET], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const k = t * t * (3 - 2 * t);
  const mag = elozo.mag + (most.mag - elozo.mag) * k;
  const rx = elozo.rx + (most.rx - elozo.rx) * k;
  const ry = elozo.ry + (most.ry - elozo.ry) * k;
  return (
    <div style={{ position: 'absolute', left: 0, top: 0, width: W, height: mag, background: C.tintakek, overflow: 'hidden' }}>
      <Rozetta x={rx} y={ry} forgas={f * 0.035} />
    </div>
  );
};

const Felirat: React.FC = () => {
  const f = useCurrentFrame();
  const c = adat.cues.find((q) => f >= q.tol - 2 && f < q.ig + 6);
  if (!c) return null;
  const sor = adat.sorok.find((s) => c.tol >= s.tol - 1 && c.ig <= s.ig + 1);
  if (sor && NINCS_FELIRAT.has(sor.id)) return null;
  const jel = adat.jelenetek.find((j) => f >= j.tol && f < j.ig);
  const sotet = jel ? savOf(jel.id).mag > 1500 : false;
  const p = Math.min(be(f, c.tol - 2, 5), 1 - be(f, c.ig + 1, 5));
  return (
    <div style={{ position: 'absolute', left: M, right: M, bottom: 196, display: 'flex', justifyContent: 'center', opacity: p }}>
      <div
        style={{
          maxWidth: W - 2 * M,
          background: sotet ? '#FFFFFF' : C.tintakek,
          color: sotet ? C.tinta : '#FFFFFF',
          borderRadius: 30,
          padding: '20px 36px 22px',
          fontSize: 52,
          fontWeight: 600,
          lineHeight: 1.28,
          letterSpacing: '-0.012em',
          textAlign: 'center',
          boxShadow: '0 18px 40px -18px rgba(16,21,60,.55)',
          textWrap: 'balance',
        } as React.CSSProperties}
      >
        {c.szoveg}
      </div>
    </div>
  );
};

export const BekotesVideo: React.FC = () => {
  useGeist();
  return (
    <AbsoluteFill style={{ background: C.alap, fontFamily: BETU, color: C.tinta, fontOpticalSizing: 'auto' } as React.CSSProperties}>
      <Sav />
      {adat.jelenetek.map((j: Jel, idx) => {
        const Komp = JELENETEK[j.id];
        if (!Komp) return null;
        const dur = j.ig - j.tol;
        const utolso = idx === adat.jelenetek.length - 1;
        const hossz = utolso ? dur : dur + KI_ATMENET;
        return (
          <Sequence key={j.id + j.tol} from={j.tol} durationInFrames={hossz} layout="none">
            <JelenetKeret j={j} dur={dur} utolso={utolso} Komp={Komp} />
          </Sequence>
        );
      })}
      <Felirat />
    </AbsoluteFill>
  );
};

const JelenetKeret: React.FC<{ j: Jel; dur: number; utolso: boolean; Komp: React.FC<JP> }> = ({ j, dur, utolso, Komp }) => {
  const f = useCurrentFrame();
  const L = (id: string) => (SOR[id] ? SOR[id].tol - j.tol : 0);
  const cue = (id: string, i: number) => {
    const cs = CUE_SORONKENT[id] || [];
    const c = cs[Math.min(i, cs.length - 1)];
    return c ? c.tol - j.tol : L(id);
  };
  const ki = utolso ? 1 : el(f, dur + KI_ATMENET, KI_ATMENET);
  return (
    <AbsoluteFill style={{ opacity: ki }}>
      <Komp f={f} L={L} cue={cue} dur={dur} />
    </AbsoluteFill>
  );
};
